#include <cstring> // For strncpy and strlen

class UltrasonicSensor {
private:
    // HC-04 variables
    uint8_t _trigPin;
    uint8_t _echoPin;
    long _duration;
    char _id[3]; // Assuming IDs are two characters plus null terminator

public:
    // Constructor
    UltrasonicSensor(const char id[3]) {
        // Validate the length of the id
        if (strlen(id) >= sizeof(_id)) {
            // Handle error: id is too long
            // For simplicity, we'll just terminate the program here
            // In a real-world scenario, you might want to log an error or throw an exception
            std::cerr << "Error: ID is too long." << std::endl;
            exit(EXIT_FAILURE);
        }

        // Copy characters from the provided id to the _id array
        strncpy(_id, id, sizeof(_id) - 1);
        // Ensure null termination
        _id[sizeof(_id) - 1] = '\0';
    }

    // ... rest of the class
};
